  <style>
    :root { font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
    body { max-width: 760px; margin: 0 auto; padding: 48px 24px; }
    h1 { margin-top: 0; }
    form { display: flex; gap: 12px; align-items: end; flex-wrap: wrap; }
    label { display: grid; gap: 6px; font-weight: 600; }
